<script>
window.FARAST_EDITOR=true;
(()=>{
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], csrf=$('meta[name=csrf-token]').content, editor=$('#editor'), source=$('#source'), analyze=$('#analyze');
let docId=null,interactionId=null,requestId=null,saveTimer=null,zoom=1;
const nf=n=>new Intl.NumberFormat('fa-IR').format(Number(n||0));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function setStatus(t,ok=false){$('#statusText').textContent=t;$('#saveState').textContent=ok?'ذخیره شد':t}
function api(url,opts={}){opts.headers={...(opts.headers||{}),'X-CSRF-TOKEN':csrf,'Accept':'application/json'};return fetch(url,opts).then(async r=>{let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.message||'خطا در ارتباط با سرور');return j})}
function cmd(c,v=null){editor.focus();document.execCommand(c,false,v);scheduleSave()}
$$('[data-cmd]').forEach(b=>b.onclick=()=>cmd(b.dataset.cmd));
$('#fontName').onchange=e=>cmd('fontName',e.target.value);$('#fontSize').onchange=e=>cmd('fontSize',e.target.value==='16'?4:Math.max(1,Math.min(7,Math.round(Number(e.target.value)/4))));
$$('[data-style]').forEach(b=>b.onclick=()=>cmd('formatBlock','<'+b.dataset.style+'>'));
$('#lineSpacing').onclick=()=>{editor.style.lineHeight=editor.style.lineHeight==='2.4'?'2.0':'2.4';scheduleSave()};
$('#direction').onclick=()=>{editor.dir=editor.dir==='rtl'?'ltr':'rtl';$('#direction').textContent=editor.dir==='rtl'?'راست به چپ':'چپ به راست';scheduleSave()};
$$('.word-tab').forEach(tab=>tab.onclick=()=>{$$('.word-tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');$$('.ribbon-secondary').forEach(x=>x.classList.add('hidden'));if(tab.dataset.tab!=='home')$('#ribbon-'+tab.dataset.tab).classList.remove('hidden')});
source.onchange=()=>{analyze.disabled=!source.files.length;if(source.files[0]){$('#sourceName').textContent=source.files[0].name;$('#sourceMeta').textContent=(source.files[0].size/1048576).toFixed(2)+' MB • آماده پردازش'}};
analyze.onclick=async()=>{if(!source.files.length)return;setStatus('در حال ارسال به Gemini…');$('#aiStatus').textContent='در حال پردازش';analyze.disabled=true;let fd=new FormData();fd.append('source',source.files[0]);try{let up=await fetch('/editor/upload',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:fd}),uj=await up.json();if(!up.ok)throw new Error(uj.message||'آپلود ناموفق بود');let j=await api('/editor/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:uj.path,mime:uj.mime,source_name:uj.name})});docId=j.document_id;interactionId=j.interaction_id;requestId=j.request_id;$('#interactionId').textContent=interactionId||'—';$('#requestId').textContent=requestId||'—';$('#aiStatus').textContent='تکمیل شد';renderAi(j);setStatus('رونویسی کامل شد',true);saveNow()}catch(e){$('#aiStatus').textContent='خطا';setStatus(e.message);alert(e.message)}finally{analyze.disabled=!source.files.length}};
function renderAi(j){editor.innerHTML=j.html||'<p><br></p>';$('#pages').textContent=nf(j.pages);$('#words').textContent=nf(j.text?.trim().split(/\s+/u).filter(Boolean).length);$('#statusWords').textContent=$('#words').textContent;$('#price').textContent=nf(j.price)+' ریال';renderIssues(j.issues||[]);bindUncertain();updatePages()}
function renderIssues(xs){$('#issues').innerHTML=xs.length?xs.map(x=>`<div class="issue-card"><mark>${esc(x.word)}</mark><div>${(x.suggestions||[]).map(s=>`<button type="button" data-word="${esc(x.word)}" data-s="${esc(s)}">${esc(s)}</button>`).join('')}</div></div>`).join(''):'<div class="empty-issues">مورد مشکوکی ثبت نشده است.</div>';$$('.issue-card button').forEach(b=>b.onclick=()=>replaceUncertainValue(b.dataset.word,b.dataset.s))}
function bindUncertain(){$$('.ai-uncertain').forEach(el=>el.onclick=e=>{e.stopPropagation();$('#aiWord').textContent=el.dataset.original;let ss=[];try{ss=JSON.parse(el.dataset.suggestions||'[]')}catch{}$('#aiSuggestions').innerHTML=ss.map(s=>`<button data-s="${esc(s)}">${esc(s)}</button>`).join('');$$('#aiSuggestions button').forEach(b=>b.onclick=()=>applySuggestion(el,b.dataset.s));$('#aiPopover').classList.remove('hidden');let r=el.getBoundingClientRect();$('#aiPopover').style.top=(r.bottom+scrollY+8)+'px';$('#aiPopover').style.left=Math.max(20,r.left+scrollX-120)+'px'})}
function applySuggestion(el,s){let original=el.dataset.original;el.replaceWith(document.createTextNode(s));sendFeedback('word_correction',original,s,'ocr_uncertain');$('#aiPopover').classList.add('hidden');scheduleSave()}
function replaceUncertainValue(word,s){let el=$$('.ai-uncertain').find(x=>x.dataset.original===word);if(el)applySuggestion(el,s)}
$('#keepWord').onclick=()=>$('#aiPopover').classList.add('hidden');document.addEventListener('click',e=>{if(!e.target.closest('.ai-popover')&&!e.target.closest('.ai-uncertain'))$('#aiPopover').classList.add('hidden')});
function sendFeedback(type,original='',corrected='',category='',note='',rating=null){if(!docId)return;api('/editor/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:docId,ai_interaction_id:interactionId,type,rating,category,original_text:original,corrected_text:corrected,note,context:{request_id:requestId,editor_version:'word-ribbon-v2'}})}).catch(()=>{})}
$('#rate5').onclick=()=>{sendFeedback('rating','','','','',5);setStatus('بازخورد شما ثبت شد',true)};$('#rate1').onclick=()=>{sendFeedback('rating','','','','',1);setStatus('بازخورد شما ثبت شد',true)};$('#feedbackGood').onclick=()=>{sendFeedback('rating','','','','',5);setStatus('بازخورد ثبت شد',true)};$('#feedbackBad').onclick=()=>{sendFeedback('wrong_output','','','','خروجی OCR نیاز به بررسی انسانی دارد',1);setStatus('بازخورد ثبت شد',true)};$('#feedbackPanelBtn').onclick=()=>$('#aiSidebar').classList.remove('collapsed');
function scheduleSave(){if(!docId)return;$('#saveState').textContent='در حال تغییر…';clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,900)}
async function saveNow(){if(!docId)return;try{let j=await api('/editor/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:docId,content:editor.innerHTML})});setStatus('ذخیره شد',true);return j}catch(e){setStatus('ذخیره ناموفق')}}
$('#saveNow').onclick=saveNow;editor.addEventListener('input',()=>{updateWords();scheduleSave()});
function updateWords(){let t=editor.innerText.trim();$('#statusWords').textContent=nf(t?t.split(/\s+/u).filter(Boolean).length:0)}
function updatePages(){let count=Math.max(1,Math.ceil(editor.scrollHeight/1050));$('#totalPages').textContent=nf(count);$('#pages').textContent=nf(count)}
$('#zoomIn').onclick=()=>setZoom(zoom+.1);$('#zoomOut').onclick=()=>setZoom(zoom-.1);function setZoom(z){zoom=Math.min(1.5,Math.max(.7,z));$('#zoomValue').textContent=Math.round(zoom*100)+'%';$('.word-page').style.transform=`scale(${zoom})`;$('.word-page').style.transformOrigin='top center'}
$('#showAi').onclick=()=>$('#aiSidebar').classList.toggle('collapsed');$('#closeAi').onclick=()=>$('#aiSidebar').classList.add('collapsed');$('#pageBreak').onclick=()=>{editor.focus();document.execCommand('insertHTML',false,'<div class="page-break" contenteditable="false"><span>صفحه جدید</span></div><p><br></p>');scheduleSave()};$('#insertDate').onclick=()=>cmd('insertText',new Intl.DateTimeFormat('fa-IR').format(new Date()));
$('#insertLink').onclick=()=>{let u=prompt('نشانی پیوند را وارد کنید');if(u)cmd('createLink',u)};$('#clearLink').onclick=()=>cmd('unlink');$('#pasteText').onclick=async()=>{try{cmd('insertText',await navigator.clipboard.readText())}catch{alert('دسترسی به کلیپ‌بورد توسط مرورگر مسدود شده است.')}};
$('#findText').onclick=()=>{$('#findDialog').classList.remove('hidden');$('#findInput').focus()};$('#replaceText').onclick=()=>{$('#findDialog').classList.remove('hidden');$('#replaceInput').focus()};$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).classList.add('hidden'));$('#findNext').onclick=()=>{let q=$('#findInput').value;if(q)window.find(q)};$('#replaceOne').onclick=()=>{let q=$('#findInput').value,r=$('#replaceInput').value;if(q&&window.find(q)){document.execCommand('insertText',false,r);scheduleSave()}};$('#replaceAll').onclick=()=>{let q=$('#findInput').value,r=$('#replaceInput').value;if(!q)return;editor.innerHTML=editor.innerHTML.split(q).join(esc(r));scheduleSave()};
$('#exportDocx').onclick=()=>exportDoc('docx');$('#exportPdf').onclick=()=>exportDoc('pdf');async function exportDoc(format){if(!docId)return alert('ابتدا یک فایل را با AI پردازش کنید');await saveNow();let f=document.createElement('form');f.method='POST';f.action='/editor/export/'+format;f.innerHTML='<input type="hidden" name="_token" value="'+csrf+'"><input type="hidden" name="document_id" value="'+docId+'">';document.body.appendChild(f);f.submit()}
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){const rec=new SR();rec.lang='fa-IR';rec.continuous=true;rec.interimResults=false;$('#mic').onclick=()=>{if($('#mic').classList.toggle('recording')){rec.start();$('#mic').textContent='⏹ توقف صوت'}else rec.stop()};rec.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)t+=e.results[i][0].transcript+' ';if(t){editor.focus();document.execCommand('insertText',false,t);scheduleSave()}};rec.onend=()=>{$('#mic').classList.remove('recording');$('#mic').textContent='🎙 صوت'}}else $('#mic').title='تایپ صوتی داخلی مرورگر در دسترس نیست';
setInterval(()=>fetch('/editor/heartbeat',{method:'POST',headers:{'X-CSRF-TOKEN':csrf}}),60000);updateWords();
})();
</script>
@endpush
